-- Bounded validator for the JSON Schema subset generated by the strict API model.
-- The schema is fixed in this migration, never supplied by the caller.
create function public.trainer_json_matches(v jsonb, s jsonb, root_schema jsonb, depth integer default 0)
returns boolean language plpgsql immutable set search_path='' as $$
declare k text; child jsonb; rule jsonb; kind text; matched boolean;
begin
  if depth>32 then return false; end if;
  if s ? '$ref' then
    return public.trainer_json_matches(v,root_schema->'$defs'->split_part(s->>'$ref','/',3),root_schema,depth+1);
  end if;
  if s ? 'anyOf' then
    for rule in select * from jsonb_array_elements(s->'anyOf') loop
      if public.trainer_json_matches(v,rule,root_schema,depth+1) then return true; end if;
    end loop;
    return false;
  end if;
  if s ? 'enum' and not exists(select 1 from jsonb_array_elements(s->'enum') e where e=v) then return false; end if;
  kind:=s->>'type';
  if kind is null then return false; end if;
  if kind='integer' then
    if jsonb_typeof(v)<>'number' or v::text !~ '^-?[0-9]+$' then return false; end if;
  elsif kind<>jsonb_typeof(v) then return false;
  end if;
  if kind in ('integer','number') then
    if s ? 'minimum' and (v::text)::numeric<(s->>'minimum')::numeric then return false; end if;
    if s ? 'maximum' and (v::text)::numeric>(s->>'maximum')::numeric then return false; end if;
  elsif kind='string' then
    if s ? 'minLength' and length(v #>> '{}')<(s->>'minLength')::int then return false; end if;
    if s ? 'maxLength' and length(v #>> '{}')>(s->>'maxLength')::int then return false; end if;
    if s ? 'pattern' and (v #>> '{}') !~ (s->>'pattern') then return false; end if;
  elsif kind='object' then
    for k in select jsonb_array_elements_text(coalesce(s->'required','[]'::jsonb)) loop
      if not (v ? k) then return false; end if;
    end loop;
    for k,child in select * from jsonb_each(v) loop
      if s->'properties' ? k then rule:=s->'properties'->k;
      elsif s->'additionalProperties'='false'::jsonb then return false;
      elsif jsonb_typeof(s->'additionalProperties')='object' then rule:=s->'additionalProperties';
      else continue;
      end if;
      if not public.trainer_json_matches(child,rule,root_schema,depth+1) then return false; end if;
    end loop;
  elsif kind='array' then
    if s ? 'minItems' and jsonb_array_length(v)<(s->>'minItems')::int then return false; end if;
    if s ? 'maxItems' and jsonb_array_length(v)>(s->>'maxItems')::int then return false; end if;
    if s ? 'items' then
      for child in select * from jsonb_array_elements(v) loop
        if not public.trainer_json_matches(child,s->'items',root_schema,depth+1) then return false; end if;
      end loop;
    end if;
  end if;
  return true;
end $$;
revoke all on function public.trainer_json_matches(jsonb,jsonb,jsonb,integer) from public,anon,authenticated;

-- Ownership is always auth.uid(); aliases are display data, never credentials.
create table public.trainer_profiles (
  owner_id uuid primary key references auth.users(id) on delete cascade,
  github_id text not null,
  alias text not null check (length(alias) between 1 and 100)
);
create table public.trainer_saves (
  owner_id uuid primary key references public.trainer_profiles(owner_id) on delete cascade,
  revision bigint not null check (revision > 0),
  schema_version integer not null default 1 check (schema_version = 1),
  core jsonb not null check (jsonb_typeof(core) = 'object'),
  updated_at timestamptz not null default now()
);
create table public.trainer_collection (
  owner_id uuid not null references public.trainer_saves(owner_id) on delete cascade,
  individual_id text not null check (length(individual_id) between 1 and 128),
  position integer not null check (position >= 0),
  base_id integer not null check (base_id between 1 and 649),
  final_id integer not null check (final_id between 1 and 649),
  shiny boolean not null,
  detail jsonb not null,
  primary key (owner_id, individual_id), unique(owner_id, position)
);
create table public.trainer_inventory (
  owner_id uuid not null references public.trainer_saves(owner_id) on delete cascade,
  kind text not null check (kind in ('rareCandy','mint','shinyCharm')),
  quantity integer not null check (quantity between 0 and 1000000),
  primary key(owner_id, kind)
);
create table public.trainer_candy_ledger (
  owner_id uuid not null references public.trainer_saves(owner_id) on delete cascade,
  ledger_key text not null check (length(ledger_key) <= 256),
  grant_tier integer check (grant_tier between 0 and 1000000),
  window_epoch text check (length(window_epoch) <= 128),
  primary key(owner_id, ledger_key)
);
create table public.trainer_save_operations (
  owner_id uuid not null references public.trainer_saves(owner_id) on delete cascade,
  request_id uuid not null,
  digest text not null,
  result_revision bigint not null,
  primary key(owner_id, request_id)
);

